import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
import {Quickbar} from '../../../src/ui/Quickbar';import {ResourceEditor} from '../../../src/ui/ResourceEditor';import {SheetEditContext} from '../../../src/ui/SheetEdit';import {newCharacter,type Character} from '../../../src/core/model';import {evaluate} from '../../../src/core/engine';import {resourceWidgetLayout,setResourceWidgetStyle} from '../../../src/core/resourceWidgets';
import '../../../src/ui/workbench.css';import '../../../src/ui/resource179.css';
const make=()=>{const c=newCharacter();c.id='resource-fixture';c.quickbarActions=['长剑','短弓','冰霜射线','灵刃'].map((name,i)=>({id:String(i),name,attack:'+5',damage:'1d8+3'}));c.runtime.resources=Object.fromEntries(['1环法术位','2环法术位','3环法术位','专注','长名称资源·晨星与暮色祝福','金币储备','灵感','恢复次数','奥术印记','旅途补给','护盾能量','治疗充能'].map((name,i)=>[i<3?`spell-slot:${i+1}`:`r${i}`,{name,current:i===5?12345:i===6?1:3,max:i===5?99999:5,type:'number',locked:i===8,unlimited:i===5}]));const ids=Object.keys(c.runtime.resources);c.quickbarLayout={order:[],hidden:[],widgets:resourceWidgetLayout(ids)};ids.forEach((id,i)=>{c.quickbarLayout!.widgets![id].style=(['bar','ring','square','icon'] as const)[i%4]});return c;};
function App(){const[c,setC]=useState<Character>(()=>{try{return JSON.parse(localStorage.getItem('widget-fixture')||'null')||make()}catch{return make()}}),[editing,setEditing]=useState(false),[resource,setResource]=useState('');const edit=(f:(c:Character)=>void)=>setC(previous=>{const next=structuredClone(previous);f(next);localStorage.setItem('widget-fixture',JSON.stringify(next));return next;});React.useEffect(()=>{const listener=(e:Event)=>setResource((e as CustomEvent).detail);window.addEventListener('edit-character-resource',listener);return()=>window.removeEventListener('edit-character-resource',listener)},[]);return <main><h1>资源模块 · 实际组件</h1><p>固定 438 × 170；12项资源，5项攻击。编辑后拖动 ⠿，八点缩放；键盘方向键移动，Shift＋方向键缩放。</p><button onClick={()=>setEditing(!editing)}>{editing?'完成编辑':'编辑布局'}</button><button onClick={()=>{localStorage.removeItem('widget-fixture');setC(make())}}>重置夹具</button><div className="fixture-frame paper"><div className="fixture-title">快捷行动与资源</div><div className="fixture-content"><SheetEditContext.Provider value={editing}><Quickbar c={c} d={evaluate(c)} edit={edit} manage={()=>setResource('r3')} manageQuickbar={()=>{}} inspect={()=>{}}/></SheetEditContext.Provider></div></div>{resource&&<ResourceEditor value={c.runtime.resources[resource]} presentation={c.quickbarLayout?.widgets?.[resource]?.style||'bar'} close={()=>setResource('')} save={async(value,style)=>edit(d=>{d.runtime.resources[resource]=value;if(style)setResourceWidgetStyle(d,resource,style)})}/>}<output id="fixture-data" style={{display:'none'}}>{JSON.stringify(c)}</output></main>};createRoot(document.getElementById('root')!).render(<App/>);

const style=document.createElement('style');style.textContent=`*{box-sizing:border-box}body{background:#c9c9c6;color:#393b42;font:14px system-ui;margin:24px}main{max-width:700px}h1{font-size:20px}p{line-height:1.6}button{cursor:pointer}main>button{margin:0 6px 12px 0;padding:6px 12px}.fixture-frame{width:438px;height:170px;background:#57585e;padding:3px;clip-path:polygon(8px 0,100% 0,100% calc(100% - 8px),calc(100% - 8px) 100%,0 100%,0 8px)}.fixture-title{height:22px;line-height:22px;color:#fff;background:#76515b;padding-left:10px;font-size:11px;font-weight:700}.fixture-content{height:142px;background:#e5e5e2}.fixture-content .quickbar-split{height:100%}@media(max-width:480px){body{margin:8px}.fixture-frame{width:100%;max-width:438px}}`;document.head.append(style);
